export const renewalPlans=[['12','سنة'],['24','سنتان'],['36','٣ سنوات'],['6','٦ أشهر']];
export function subscriptionInput(iso){if(!iso)return '';const date=new Date(iso);return new Date(date.getTime()+3*3600000).toISOString().slice(0,16)}
export function subscriptionDates(start,end){if(!start&&!end)return{subscription_starts_at:null,subscription_ends_at:null};const s=new Date(start+'+03:00'),e=new Date(end+'+03:00');if(!Number.isFinite(+s)||!Number.isFinite(+e)||e<=s)throw Error('حدد البداية والنهاية، ويجب أن تكون النهاية بعد البداية.');return{subscription_starts_at:s.toISOString(),subscription_ends_at:e.toISOString()}}
function addMonths(date,n){const d=new Date(date),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return d}
export function subscriptionDuration(start,end){let a=new Date(Date.parse(start)+3*3600000),b=new Date(Date.parse(end)+3*3600000);if(!start||!end||!Number.isFinite(+a)||!Number.isFinite(+b)||b<=a)return 'لم تحدد فترة اشتراك';let months=(b.getUTCFullYear()-a.getUTCFullYear())*12+b.getUTCMonth()-a.getUTCMonth();while(addMonths(a,months)>b)months--;a=addMonths(a,months);let minutes=Math.floor((b-a)/60000);const days=Math.floor(minutes/1440);minutes%=1440;const values=[Math.floor(months/12),months%12,Math.floor(days/7),days%7,Math.floor(minutes/60),minutes%60];const names=['سنة','شهر','أسبوع','يوم','ساعة','دقيقة'];return values.flatMap((n,i)=>n?[n+' '+names[i]]:[]).join(' و ')||'أقل من دقيقة'}
export function subscriptionStatus(t,now=Date.now()){if(!t.subscription_ends_at)return 'لم تحدد فترة اشتراك';if(now<Date.parse(t.subscription_starts_at))return 'يبدأ لاحقًا · المدة '+subscriptionDuration(t.subscription_starts_at,t.subscription_ends_at);if(now>=Date.parse(t.subscription_ends_at))return 'انتهى الاشتراك';return 'المتبقي '+subscriptionDuration(new Date(now).toISOString(),t.subscription_ends_at)}
export function subscriptionAdmin({t,element,button,busy,rpc,toast,reload}){
 const box=element('section',undefined,'subscription-admin');box.append(element('h4','فترة الاشتراك'),element('p',subscriptionStatus(t)),element('p','بعد نهاية الاشتراك يصبح الكيان للاطلاع فقط. إيقاف الدخول قرار منفصل.'));const form=element('form');
 function input(name,label,type,value=''){const l=element('label',label),i=element('input');i.type=type;i.name=name;i.value=value;l.append(i);form.append(l);return i}
 const start=input('start','من (بتوقيت الرياض)','datetime-local',subscriptionInput(t.subscription_starts_at)),end=input('end','إلى (بتوقيت الرياض)','datetime-local',subscriptionInput(t.subscription_ends_at));const duration=element('p');duration.setAttribute('role','status');function show(){try{const d=subscriptionDates(start.value,end.value);duration.textContent=subscriptionDuration(d.subscription_starts_at,d.subscription_ends_at)}catch(e){duration.textContent=e.message}}start.oninput=end.oninput=show;show();form.append(duration,element('h4','أسعار التجديد بالريال'));const prices={};for(const [key,label]of renewalPlans){const i=input(key,label,'number',t.renewal_prices?.[key]??'');i.min=0;i.max=99999999.99;i.step='.01';prices[key]=i}const save=element('button','حفظ الفترة والأسعار','primary');form.append(save);form.onsubmit=e=>{e.preventDefault();return busy(save,async()=>{const dates=subscriptionDates(start.value,end.value),renewal_prices={};for(const [k,i]of Object.entries(prices)){const raw=i.value.trim();if(raw==='')continue;const n=Number(raw);if(!Number.isFinite(n)||n<0||n>99999999.99||Math.abs(n*100-Math.round(n*100))>1e-5)throw Error('تحقق من أسعار الباقات.');renewal_prices[k]=n}await rpc('platform_action',{action:'subscription_save',data:{id:t.id,...dates,renewal_prices}});toast('حُفظت الفترة وأسعار التجديد.');await reload()})};box.append(form);
 const renew=element('div',undefined,'subscription-renew');renew.append(element('h4','تجديد الاشتراك'),element('p','يضاف إلى نهاية الاشتراك الساري، أو يبدأ الآن إذا انتهى. تسجيل السداد يدوي؛ لا يجري سحب أي مبلغ.'));const select=element('select');select.setAttribute('aria-label','باقة التجديد');for(const [k,label]of renewalPlans){const price=t.renewal_prices?.[k];const o=element('option',label+' · '+(price==null?'لم يحدد السعر':price+' ر.س'));o.value=k;o.disabled=price==null;select.append(o)}select.value=renewalPlans.find(([k])=>t.renewal_prices?.[k]!=null)?.[0]||'';renew.append(select);const paid=element('select');paid.setAttribute('aria-label','حالة سداد التجديد');for(const [v,label]of [['paid','تم السداد يدويًا'],['waived','إعفاء من الرسوم']]){const o=element('option',label);o.value=v;paid.append(o)}renew.append(paid);
 const renewButton=button('تأكيد وتجديد الاشتراك',()=>{if(!select.value)return;const d=element('dialog');d.className='tenant-renew-confirm';const label=renewalPlans.find(([k])=>k===select.value)[1],months=Number(select.value),payment_status=paid.value,request_id=crypto.randomUUID();d.append(element('h3','تأكيد التجديد'),element('p',t.name+' · '+label+' · '+(payment_status==='waived'?'إعفاء':t.renewal_prices[select.value]+' ر.س مسددة يدويًا')),element('p','سيُمدد الاشتراك بعد التأكيد. لن يتم تحصيل مبلغ إلكترونيًا.'));const confirm=button('تنفيذ التجديد',()=>busy(confirm,async()=>{await rpc('platform_action',{action:'renew',data:{id:t.id,months,payment_status,request_id}});d.close();d.remove();toast('تم تجديد الاشتراك.');await reload()}),'primary');d.append(confirm,button('إلغاء',()=>{d.close();d.remove()}));document.body.append(d);d.showModal()},'primary');renewButton.disabled=!select.value;renew.append(renewButton);box.append(renew);return box;
}
